INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('bid bond', '', '', '[{"en":"A bid bond of 2% of the contract value was required.","zh-TW":"要求合約價值2%的投標保函。"},{"en":"The bid bond protects the client if the winning bidder withdraws.","zh-TW":"如果中標者撤回，投標保函保護了客戶。"}]', 'phrasal verb'),
('billing rate', '', '', '[{"en":"The consulting firm''s billing rate is $250 per hour.","zh-TW":"諮詢公司的計費率為每小時250元。"},{"en":"Billing rates vary depending on the seniority of the assigned consultant.","zh-TW":"計費率因指派顧問的資歷不同而有所不同。"}]', 'phrasal verb'),
('block booking', '', '', '[{"en":"The conference organizer made a block booking at the hotel.","zh-TW":"會議組織者在飯店進行了整批預訂。"},{"en":"Block bookings often receive preferential rates from suppliers.","zh-TW":"整批預訂通常從供應商那裡獲得優惠費率。"}]', 'phrasal verb'),
('break clause', '', '', '[{"en":"The tenant exercised the break clause after two years.","zh-TW":"租戶在兩年後行使了解除條款。"},{"en":"A break clause adds flexibility for tenants in long lease agreements.","zh-TW":"解除條款在長期租約協議中為租戶增加了靈活性。"}]', 'phrasal verb'),
('bridge loan', '', '', '[{"en":"The company took a bridge loan to fund the acquisition while awaiting bond issuance.","zh-TW":"公司在等待債券發行期間獲取了過渡貸款以資助收購。"},{"en":"Bridge loans carry higher interest rates than long-term loans.","zh-TW":"過渡貸款的利率比長期貸款高。"}]', 'phrasal verb'),
('bulk discount', '', '', '[{"en":"A 15% bulk discount was applied to orders over 500 units.","zh-TW":"訂購超過500個單位時適用15%的批量折扣。"},{"en":"Bulk discounts incentivize larger orders and improve supply efficiency.","zh-TW":"批量折扣激勵了更大的訂單並提高了供應效率。"}]', 'phrasal verb'),
('callable bond', '', '', '[{"en":"The issuer redeemed the callable bond early when interest rates fell.","zh-TW":"當利率下降時，發行人提前贖回了可贖回債券。"},{"en":"Callable bonds typically offer higher yields to compensate for early redemption risk.","zh-TW":"可贖回債券通常提供較高的殖利率以補償提前贖回風險。"}]', 'phrasal verb'),
('closing date', '', '', '[{"en":"The closing date for the tender is 31 January.","zh-TW":"招標的截止日期為1月31日。"},{"en":"All documentation must be received by the closing date.","zh-TW":"所有文件必須在截止日期前收到。"}]', 'phrasal verb'),
('commercial paper', '', '', '[{"en":"The company raised funds through commercial paper to cover working capital.","zh-TW":"公司通過商業本票籌集資金以涵蓋營運資金。"},{"en":"Commercial paper is a cost-effective short-term financing tool.","zh-TW":"商業本票是一種具有成本效益的短期融資工具。"}]', 'phrasal verb'),
('commodities market', '', '', '[{"en":"Oil and gold are among the most traded assets in the commodities market.","zh-TW":"石油和黃金是大宗商品市場中交易最頻繁的資產之一。"},{"en":"Commodities market prices affect production costs across industries.","zh-TW":"大宗商品市場價格影響了各行業的生產成本。"}]', 'phrasal verb'),
('credit assessment', '', '', '[{"en":"Banks conduct a credit assessment before approving a loan application.","zh-TW":"銀行在批准貸款申請前進行信用評估。"},{"en":"A poor credit assessment result leads to higher interest rates or rejection.","zh-TW":"信用評估結果不佳會導致更高的利率或被拒絕。"}]', 'phrasal verb'),
('credit insurance', '', '', '[{"en":"The exporter bought credit insurance to protect against buyer default.","zh-TW":"出口商購買了信用保險以防範買方違約。"},{"en":"Credit insurance covers both commercial and political payment risks.","zh-TW":"信用保險涵蓋了商業和政治支付風險。"}]', 'phrasal verb'),
('credit management', '', '', '[{"en":"Strong credit management reduces bad debt and improves cash flow.","zh-TW":"強有力的信用管理減少了壞帳並改善了現金流。"},{"en":"The credit management team sets limits and monitors customer accounts.","zh-TW":"信用管理團隊設置限額並監控客戶帳戶。"}]', 'phrasal verb'),
('day rate', '', '', '[{"en":"The contractor''s day rate was $800 for on-site work.","zh-TW":"承包商的現場工作日費率為800元。"},{"en":"Day rates for specialized consultants vary widely by industry.","zh-TW":"專業顧問的日費率因行業不同而差異很大。"}]', 'phrasal verb'),
('debt covenant', '', '', '[{"en":"The company breached a debt covenant by failing to maintain its interest coverage ratio.","zh-TW":"公司因未能維持其利息覆蓋比率而違反了債務契約條款。"},{"en":"Debt covenants protect lenders by restricting risky borrower behavior.","zh-TW":"債務契約條款通過限制借款人的風險行為來保護貸款方。"}]', 'phrasal verb'),
('deed of assignment', '', '', '[{"en":"A deed of assignment was used to transfer the intellectual property rights.","zh-TW":"轉讓契約用於轉移知識產權。"},{"en":"The deed of assignment must be notarized to be legally enforceable.","zh-TW":"轉讓契約必須經公證才能具有法律效力。"}]', 'phrasal verb'),
('delinquent account', '', '', '[{"en":"The collections team contacts all delinquent accounts within 30 days.","zh-TW":"追收團隊在30天內聯繫所有逾期帳戶。"},{"en":"Delinquent accounts are transferred to a specialist recovery team.","zh-TW":"逾期帳戶被移交給專業追收團隊。"}]', 'phrasal verb'),
('demand elasticity', '', '', '[{"en":"Luxury goods tend to have higher demand elasticity than staples.","zh-TW":"奢侈品的需求彈性往往比主食類產品高。"},{"en":"Understanding demand elasticity is essential for effective pricing.","zh-TW":"了解需求彈性對於有效定價至關重要。"}]', 'phrasal verb'),
('deposit account', '', '', '[{"en":"The company moved surplus funds into a high-interest deposit account.","zh-TW":"公司將盈餘資金轉移到高利息存款帳戶。"},{"en":"A deposit account is suitable for funds not needed for daily transactions.","zh-TW":"存款帳戶適合不需要日常交易的資金。"}]', 'phrasal verb'),
('depreciated cost', '', '', '[{"en":"The machinery is recorded at its depreciated cost of $40000.","zh-TW":"機械以其4萬元的已折舊成本記錄。"},{"en":"Depreciated cost reflects the value remaining after accounting for wear.","zh-TW":"已折舊成本反映了計算磨損後剩餘的價值。"}]', 'phrasal verb'),
('discounted cash flow', '', '', '[{"en":"Discounted cash flow analysis values the company at $20 million.","zh-TW":"折現現金流分析將公司估值為2000萬元。"},{"en":"Discounted cash flow is the most rigorous method for investment appraisal.","zh-TW":"折現現金流是投資評估最嚴格的方法。"}]', 'phrasal verb'),
('distributor agreement', '', '', '[{"en":"The distributor agreement grants exclusive rights for three years.","zh-TW":"分銷協議授予了三年的獨家權利。"},{"en":"Terminating a distributor agreement requires compliance with notice periods.","zh-TW":"終止分銷協議需要遵守通知期限。"}]', 'phrasal verb'),
('diversification strategy', '', '', '[{"en":"The diversification strategy reduced dependency on a single revenue source.","zh-TW":"多元化策略降低了對單一收入來源的依賴。"},{"en":"A related diversification strategy leverages existing capabilities in new areas.","zh-TW":"相關多元化策略在新領域利用了現有能力。"}]', 'phrasal verb'),
('documentary credit', '', '', '[{"en":"The bank issued a documentary credit to guarantee payment for the shipment.","zh-TW":"銀行開立了跟單信用狀以保證貨運付款。"},{"en":"Documentary credits reduce risk in international trade by requiring proof of delivery.","zh-TW":"跟單信用狀通過要求交貨證明降低了國際貿易的風險。"}]', 'phrasal verb'),
('duty of care', '', '', '[{"en":"Employers have a duty of care to maintain a safe working environment.","zh-TW":"雇主有注意義務維持安全的工作環境。"},{"en":"A breach of duty of care can result in legal liability.","zh-TW":"違反注意義務可能導致法律責任。"}]', 'phrasal verb'),
('earnings before interest tax depreciation amortization', '', '', '[{"en":"EBITDA is widely used to compare operational performance across companies.","zh-TW":"EBITDA被廣泛用於比較各公司的運營績效。"},{"en":"The company''s EBITDA margin improved to 25% following cost restructuring.","zh-TW":"在成本重組後，公司的EBITDA利潤率提升至25%。"}]', 'phrasal verb'),
('effective management', '', '', '[{"en":"Effective management requires clear goals, resources, and communication.","zh-TW":"有效管理需要明確的目標、資源和溝通。"},{"en":"The program taught effective management through case studies and coaching.","zh-TW":"該計劃通過案例研究和輔導教授了有效管理。"}]', 'phrasal verb'),
('eligible expense', '', '', '[{"en":"Only eligible expenses as per the policy are reimbursed.","zh-TW":"只有符合政策的合資格費用才能報銷。"},{"en":"The accountant reviewed all receipts to identify eligible expenses.","zh-TW":"會計師審查了所有收據以識別合資格費用。"}]', 'phrasal verb'),
('employee contract', '', '', '[{"en":"Every new hire must sign an employee contract before starting.","zh-TW":"每位新員工在入職前必須簽署雇用合約。"},{"en":"The employee contract outlines duties, salary, and termination conditions.","zh-TW":"雇用合約概述了職責、薪資和終止條件。"}]', 'phrasal verb'),
('equity issuance', '', '', '[{"en":"The equity issuance raised $30 million to fund expansion.","zh-TW":"股票發行籌集了3000萬元用於擴張。"},{"en":"Equity issuance dilutes existing shareholders but avoids adding debt.","zh-TW":"股票發行稀釋了現有股東，但避免了增加債務。"}]', 'phrasal verb'),
('estimated useful life', '', '', '[{"en":"The estimated useful life of the equipment is 10 years.","zh-TW":"設備的估計使用年限為10年。"},{"en":"Depreciation is calculated based on the estimated useful life of each asset.","zh-TW":"折舊根據每項資產的估計使用年限計算。"}]', 'phrasal verb'),
('exchange controls', '', '', '[{"en":"Exchange controls limited the company''s ability to repatriate profits.","zh-TW":"外匯管制限制了公司匯回利潤的能力。"},{"en":"Some developing countries impose exchange controls to protect their currency.","zh-TW":"一些發展中國家實施外匯管制以保護其貨幣。"}]', 'phrasal verb'),
('explicit cost', '', '', '[{"en":"Rent and salaries are explicit costs that appear directly on financial statements.","zh-TW":"租金和薪資是直接出現在財務報表上的顯性成本。"},{"en":"Explicit costs are easier to track and control than implicit costs.","zh-TW":"顯性成本比隱性成本更容易追蹤和控制。"}]', 'phrasal verb'),
('false advertising', '', '', '[{"en":"The company was fined for false advertising about product performance claims.","zh-TW":"公司因對產品性能聲明進行虛假廣告而被罰款。"},{"en":"False advertising damages consumer trust and invites regulatory action.","zh-TW":"虛假廣告損害了消費者信任並引發了監管行動。"}]', 'phrasal verb'),
('fee structure', '', '', '[{"en":"The consultant explained the fee structure before engagement began.","zh-TW":"顧問在開始工作前解釋了費用結構。"},{"en":"A transparent fee structure builds trust with clients.","zh-TW":"透明的費用結構建立了與客戶的信任。"}]', 'phrasal verb'),
('financial controller', '', '', '[{"en":"The financial controller ensured all regulatory filings were submitted on time.","zh-TW":"財務主任確保所有監管申報按時提交。"},{"en":"A financial controller oversees the budget process and manages the finance team.","zh-TW":"財務主任監督預算流程並管理財務團隊。"}]', 'phrasal verb'),
('financial institution', '', '', '[{"en":"All financial institutions must comply with anti-money-laundering regulations.","zh-TW":"所有金融機構必須遵守反洗錢法規。"},{"en":"The company obtained financing from a leading financial institution.","zh-TW":"公司從一家領先的金融機構獲得了融資。"}]', 'phrasal verb'),
('fiscal year-end', '', '', '[{"en":"All accounts must be finalized for fiscal year-end reporting.","zh-TW":"所有帳目必須在財務年度末報告前完成。"},{"en":"The fiscal year-end is March 31 for most Japanese companies.","zh-TW":"大多數日本公司的財務年度末為3月31日。"}]', 'phrasal verb'),
('floor price', '', '', '[{"en":"The government set a floor price for agricultural products to protect farmers.","zh-TW":"政府為農產品設定了底價以保護農民。"},{"en":"Auction items start at the floor price established by the seller.","zh-TW":"拍賣物品從賣方設定的底價開始。"}]', 'phrasal verb'),
('follow-up communication', '', '', '[{"en":"A follow-up communication after the meeting confirmed next steps.","zh-TW":"會議後的後續溝通確認了後續步驟。"},{"en":"Timely follow-up communication strengthens client relationships.","zh-TW":"及時的後續溝通加強了客戶關係。"}]', 'phrasal verb'),
('fronting arrangement', '', '', '[{"en":"The company used a fronting arrangement to write insurance in markets where it lacked a license.","zh-TW":"公司在沒有許可證的市場使用了先頭安排來發行保單。"},{"en":"A fronting arrangement involves paying fees to the fronting insurer.","zh-TW":"先頭安排涉及向先頭保險公司支付費用。"}]', 'phrasal verb'),
('global sourcing', '', '', '[{"en":"Global sourcing allows companies to reduce costs by buying from low-cost markets.","zh-TW":"全球採購允許公司通過從低成本市場購買來降低成本。"},{"en":"Managing quality and logistics is a key challenge in global sourcing.","zh-TW":"管理品質和物流是全球採購的主要挑戰。"}]', 'phrasal verb'),
('going concern opinion', '', '', '[{"en":"The auditor issued a going concern opinion due to ongoing losses.","zh-TW":"審計師因持續虧損而發表了持續經營意見。"},{"en":"Management must address the issues raised in a going concern opinion.","zh-TW":"管理層必須解決持續經營意見中提出的問題。"}]', 'phrasal verb'),
('grace period interest', '', '', '[{"en":"The borrower agreed to pay grace period interest at half the standard rate.","zh-TW":"借款人同意以標準利率的一半支付寬限期利息。"},{"en":"Grace period interest was waived as part of the debt restructuring deal.","zh-TW":"寬限期利息作為債務重組協議的一部分被豁免了。"}]', 'phrasal verb'),
('horizontal merger', '', '', '[{"en":"The horizontal merger created the country''s largest retail chain.","zh-TW":"橫向合併創造了該國最大的零售連鎖。"},{"en":"Regulators scrutinize horizontal mergers for anti-competitive effects.","zh-TW":"監管機構對橫向合併進行反競爭效果審查。"}]', 'phrasal verb'),
('industry analysis', '', '', '[{"en":"Porter''s Five Forces is a common framework for industry analysis.","zh-TW":"波特五力模型是行業分析的常用框架。"},{"en":"Industry analysis helps businesses identify opportunities and threats.","zh-TW":"行業分析幫助企業識別機會和威脅。"}]', 'phrasal verb'),
('industry standard', '', '', '[{"en":"The product was designed to comply with international industry standards.","zh-TW":"產品被設計為符合國際行業標準。"},{"en":"Industry standards ensure consistency and safety across products.","zh-TW":"行業標準確保了產品的一致性和安全性。"}]', 'phrasal verb'),
('inherent risk', '', '', '[{"en":"The inherent risk of cash handling is higher without strong internal controls.","zh-TW":"在沒有強有力內部控制的情況下，現金處理的固有風險較高。"},{"en":"Auditors assess the inherent risk before planning audit procedures.","zh-TW":"審計師在規劃審計程序前評估固有風險。"}]', 'phrasal verb'),
('internal controls', '', '', '[{"en":"Strong internal controls reduce the risk of fraud and error.","zh-TW":"強有力的內部控制降低了欺詐和錯誤的風險。"},{"en":"Auditors evaluate the effectiveness of internal controls during their review.","zh-TW":"審計師在審查期間評估內部控制的有效性。"}]', 'phrasal verb'),
('invoice financing', '', '', '[{"en":"Invoice financing provided liquidity while waiting for customer payments.","zh-TW":"在等待客戶付款期間，發票融資提供了流動性。"},{"en":"Invoice financing is particularly useful for businesses with long payment cycles.","zh-TW":"對於付款週期長的企業來說，發票融資特別有用。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('key man risk', '', '', '[{"en":"The company purchased key man risk insurance on its founder.","zh-TW":"公司為其創辦人購買了關鍵人物風險保險。"},{"en":"Key man risk is reduced by developing succession plans and cross-training.","zh-TW":"通過制定接班計劃和交叉培訓可以降低關鍵人物風險。"}]', 'phrasal verb'),
('landed cost', '', '', '[{"en":"The landed cost of the imported machinery was 20% above the factory price.","zh-TW":"進口機械的到岸成本比出廠價高出20%。"},{"en":"Understanding landed cost is essential for accurate product pricing.","zh-TW":"了解到岸成本對於準確的產品定價至關重要。"}]', 'phrasal verb'),
('liquidity event', '', '', '[{"en":"An IPO is the most common form of liquidity event for startups.","zh-TW":"首次公開招股是初創企業最常見的流動性事件形式。"},{"en":"Early investors were waiting for a liquidity event to realize their gains.","zh-TW":"早期投資者正在等待流動性事件以實現其收益。"}]', 'phrasal verb'),
('liquidity management', '', '', '[{"en":"Effective liquidity management prevents cash shortfalls.","zh-TW":"有效的流動性管理防止了現金短缺。"},{"en":"The treasury team monitors cash positions daily for liquidity management.","zh-TW":"財務團隊每日監控現金狀況以進行流動性管理。"}]', 'phrasal verb'),
('listing requirements', '', '', '[{"en":"The company reorganized its board to meet listing requirements.","zh-TW":"公司重組了董事會以滿足上市要求。"},{"en":"Listing requirements include minimum revenue thresholds and governance standards.","zh-TW":"上市要求包括最低收入門檻和治理標準。"}]', 'phrasal verb'),
('lump sum payment', '', '', '[{"en":"The client chose a lump sum payment to avoid ongoing monthly fees.","zh-TW":"客戶選擇一次性付款以避免持續的月費。"},{"en":"A lump sum payment may attract a discount from the supplier.","zh-TW":"一次性付款可能從供應商那裡獲得折扣。"}]', 'phrasal verb'),
('marginal cost', '', '', '[{"en":"Marginal cost decreases as production volume rises due to fixed cost spreading.","zh-TW":"由於固定成本分攤，邊際成本隨著生產量增加而降低。"},{"en":"Pricing below marginal cost is not sustainable in the long run.","zh-TW":"長期來看，定價低於邊際成本是不可持續的。"}]', 'phrasal verb'),
('market failure', '', '', '[{"en":"Negative externalities are a classic example of market failure.","zh-TW":"負外部性是市場失靈的典型例子。"},{"en":"Government intervention aims to correct market failure in public goods.","zh-TW":"政府幹預旨在糾正公共物品方面的市場失靈。"}]', 'phrasal verb'),
('market outlook', '', '', '[{"en":"The analyst presented a positive market outlook for consumer goods.","zh-TW":"分析師對消費品提出了積極的市場前景。"},{"en":"A weak market outlook may delay investment decisions.","zh-TW":"疲軟的市場前景可能會推遲投資決策。"}]', 'phrasal verb'),
('master franchise', '', '', '[{"en":"The company awarded a master franchise for the Middle East region.","zh-TW":"公司授予了中東地區的總特許經營權。"},{"en":"Master franchise holders are responsible for supporting sub-franchisees.","zh-TW":"總特許經營權持有人負責支援子加盟商。"}]', 'phrasal verb'),
('medium-term note', '', '', '[{"en":"The company issued $100 million in medium-term notes.","zh-TW":"公司發行了1億元的中期票據。"},{"en":"Medium-term notes are used to diversify a company''s debt maturity profile.","zh-TW":"中期票據用於多元化公司的債務到期期限結構。"}]', 'phrasal verb'),
('mergers and acquisitions', '', '', '[{"en":"The company''s mergers and acquisitions activity tripled over five years.","zh-TW":"公司的合併與收購活動在五年內增加了兩倍。"},{"en":"Mergers and acquisitions advisors are hired to negotiate deal terms.","zh-TW":"聘用合併與收購顧問來談判交易條款。"}]', 'phrasal verb'),
('money market', '', '', '[{"en":"Surplus funds were placed in money market instruments overnight.","zh-TW":"多餘資金被投入隔夜貨幣市場工具。"},{"en":"Money market rates influence the cost of short-term business financing.","zh-TW":"貨幣市場利率影響了短期商業融資成本。"}]', 'phrasal verb'),
('moral hazard', '', '', '[{"en":"Insurance creates moral hazard by reducing the insured''s incentive to avoid loss.","zh-TW":"保險通過降低被保險人避免損失的動力而產生了道德風險。"},{"en":"Moral hazard is a major concern in government bailouts of failing companies.","zh-TW":"道德風險是政府援助破產公司時的主要擔憂。"}]', 'phrasal verb'),
('multiyear contract', '', '', '[{"en":"The client signed a multiyear contract for ongoing consulting services.","zh-TW":"客戶簽署了持續諮詢服務的多年合約。"},{"en":"A multiyear contract provides revenue stability and planning certainty.","zh-TW":"多年合約提供了收入穩定性和規劃確定性。"}]', 'phrasal verb'),
('net realizable value', '', '', '[{"en":"Inventory is carried at the lower of cost or net realizable value.","zh-TW":"庫存以成本或淨變現價值中的較低者計列。"},{"en":"Net realizable value is key in testing inventory for impairment.","zh-TW":"淨變現價值是測試庫存減值的關鍵。"}]', 'phrasal verb'),
('nominal growth', '', '', '[{"en":"Nominal growth was 8%, but real growth after inflation was only 3%.","zh-TW":"名目增長為8%，但扣除通脹後的實際增長僅為3%。"},{"en":"Investors track both nominal and real growth to understand true economic performance.","zh-TW":"投資者追蹤名目和實際增長以了解真實的經濟表現。"}]', 'phrasal verb'),
('officer of the court', '', '', '[{"en":"The receiver was appointed as an officer of the court to manage the estate.","zh-TW":"接管人被任命為法庭人員以管理資產。"},{"en":"An officer of the court has legal and ethical obligations beyond their client.","zh-TW":"法庭人員對其客戶之外有法律和道德義務。"}]', 'phrasal verb'),
('open-ended fund', '', '', '[{"en":"An open-ended fund allows investors to redeem shares at any time.","zh-TW":"開放式基金允許投資者隨時贖回股份。"},{"en":"Open-ended funds are priced daily based on net asset value.","zh-TW":"開放式基金根據淨資產值每日定價。"}]', 'phrasal verb'),
('operational risk', '', '', '[{"en":"The company identified human error as its highest operational risk.","zh-TW":"公司確定了人為錯誤作為其最高的運營風險。"},{"en":"An operational risk management system helps prevent financial losses.","zh-TW":"運營風險管理系統有助於防止財務損失。"}]', 'phrasal verb'),
('order confirmation', '', '', '[{"en":"Customers receive an order confirmation by email within minutes.","zh-TW":"客戶在幾分鐘內通過電子郵件收到訂單確認。"},{"en":"Check the order confirmation for accuracy before proceeding.","zh-TW":"在繼續之前檢查訂單確認的準確性。"}]', 'phrasal verb'),
('outstanding shares', '', '', '[{"en":"The company had 10 million outstanding shares before the buyback.","zh-TW":"在回購前，公司有1000萬股已發行流通股。"},{"en":"Earnings per share is calculated using the number of outstanding shares.","zh-TW":"每股盈餘使用已發行流通股數量計算。"}]', 'phrasal verb'),
('paid-up capital', '', '', '[{"en":"The company increased its paid-up capital to meet regulatory requirements.","zh-TW":"公司增加了實收資本以滿足監管要求。"},{"en":"Paid-up capital represents the actual investment made by shareholders.","zh-TW":"實收資本代表了股東的實際投資。"}]', 'phrasal verb'),
('parent company guarantee', '', '', '[{"en":"The landlord required a parent company guarantee for the subsidiary''s lease.","zh-TW":"房東要求母公司為子公司的租約提供擔保。"},{"en":"A parent company guarantee reduces credit risk in large contracts.","zh-TW":"母公司擔保降低了大型合約中的信用風險。"}]', 'phrasal verb'),
('partnership agreement', '', '', '[{"en":"The partnership agreement specified each partner''s capital contribution.","zh-TW":"合夥協議規定了每位合夥人的資本出資。"},{"en":"Disputes between partners are governed by the partnership agreement.","zh-TW":"合夥人之間的糾紛由合夥協議管轄。"}]', 'phrasal verb'),
('payables management', '', '', '[{"en":"Effective payables management optimizes cash flow by timing payments.","zh-TW":"有效的應付帳款管理通過安排付款時間來優化現金流。"},{"en":"The finance team reviews payables management metrics monthly.","zh-TW":"財務團隊每月審查應付帳款管理指標。"}]', 'phrasal verb'),
('payout ratio', '', '', '[{"en":"A payout ratio above 80% leaves little for reinvestment.","zh-TW":"高於80%的股息支付比率幾乎沒有留下再投資的空間。"},{"en":"Growth companies tend to have lower payout ratios.","zh-TW":"成長型公司往往有較低的股息支付比率。"}]', 'phrasal verb'),
('peak demand', '', '', '[{"en":"Extra staff were hired to handle peak demand during the holiday season.","zh-TW":"額外員工被聘用以處理假期季節的需求高峰。"},{"en":"Forecasting peak demand allows inventory to be stocked in advance.","zh-TW":"預測需求高峰允許提前備貨。"}]', 'phrasal verb'),
('peer comparison', '', '', '[{"en":"The peer comparison showed the company ranked third in profit margins.","zh-TW":"同業比較顯示公司在利潤率方面排名第三。"},{"en":"Investors use peer comparison to identify undervalued stocks.","zh-TW":"投資者使用同業比較來識別被低估的股票。"}]', 'phrasal verb'),
('physical inventory', '', '', '[{"en":"A physical inventory is conducted at every quarter end.","zh-TW":"每季度末進行實地盤點。"},{"en":"Discrepancies found during physical inventory trigger an investigation.","zh-TW":"實地盤點中發現的差異會引發調查。"}]', 'phrasal verb'),
('pipeline revenue', '', '', '[{"en":"The sales team''s pipeline revenue suggests strong growth next quarter.","zh-TW":"銷售團隊的管道收入顯示下季度將有強勁增長。"},{"en":"Pipeline revenue analysis helps management assess future cash flow.","zh-TW":"管道收入分析幫助管理層評估未來現金流。"}]', 'phrasal verb'),
('position paper', '', '', '[{"en":"The industry submitted a position paper opposing the new regulation.","zh-TW":"該行業提交了一份反對新法規的立場文件。"},{"en":"A position paper helps align stakeholders before a negotiation.","zh-TW":"立場文件有助於在談判前協調利害關係人。"}]', 'phrasal verb'),
('predatory pricing', '', '', '[{"en":"Regulators investigated the company for predatory pricing practices.","zh-TW":"監管機構調查了公司的掠奪性定價行為。"},{"en":"Predatory pricing is illegal in many jurisdictions.","zh-TW":"掠奪性定價在許多司法管轄區是非法的。"}]', 'phrasal verb'),
('pricing model', '', '', '[{"en":"The company switched to a subscription pricing model.","zh-TW":"公司切換到了訂閱定價模型。"},{"en":"A value-based pricing model focuses on perceived customer benefit.","zh-TW":"基於價值的定價模型側重於客戶感知的效益。"}]', 'phrasal verb'),
('price war', '', '', '[{"en":"The price war between rivals eroded margins across the industry.","zh-TW":"競爭對手之間的價格戰侵蝕了整個行業的利潤率。"},{"en":"A price war benefits consumers in the short term but harms all competitors.","zh-TW":"價格戰在短期內有利於消費者，但對所有競爭者都有害。"}]', 'phrasal verb'),
('prime rate', '', '', '[{"en":"The loan was priced at prime rate plus 2%.","zh-TW":"貸款以基準利率加2%定價。"},{"en":"A rise in the prime rate increases borrowing costs across the economy.","zh-TW":"基準利率上升增加了整個經濟的借貸成本。"}]', 'phrasal verb'),
('pro rata', '', '', '[{"en":"The bonus was paid on a pro rata basis for partial-year employees.","zh-TW":"獎金按比例支付給部分年度員工。"},{"en":"Costs were allocated pro rata based on each division''s revenue.","zh-TW":"成本根據每個部門的收入按比例分配。"}]', 'phrasal verb'),
('profitability analysis', '', '', '[{"en":"Profitability analysis showed that three product lines drove 80% of earnings.","zh-TW":"盈利能力分析顯示三條產品線帶來了80%的收益。"},{"en":"The team conducted a customer profitability analysis to prioritize retention.","zh-TW":"團隊進行了客戶盈利能力分析以確定留存優先順序。"}]', 'phrasal verb'),
('projected earnings', '', '', '[{"en":"Analysts raised projected earnings after the strong Q2 results.","zh-TW":"在強勁的第二季度業績後，分析師上調了預計盈利。"},{"en":"Missing projected earnings can trigger a sharp stock price decline.","zh-TW":"未達預計盈利可能觸發股價急跌。"}]', 'phrasal verb'),
('public company', '', '', '[{"en":"Becoming a public company requires meeting stock exchange requirements.","zh-TW":"成為上市公司需要滿足股票交易所的要求。"},{"en":"A public company must publish quarterly financial results.","zh-TW":"上市公司必須公布季度財務業績。"}]', 'phrasal verb'),
('purchase ledger', '', '', '[{"en":"All supplier invoices are posted to the purchase ledger.","zh-TW":"所有供應商發票都被過帳到採購分類帳。"},{"en":"The purchase ledger is reconciled monthly against supplier statements.","zh-TW":"採購分類帳每月根據供應商對帳單進行核對。"}]', 'phrasal verb'),
('quality improvement', '', '', '[{"en":"The quality improvement program reduced defect rates by half.","zh-TW":"品質改善計劃將缺陷率降低了一半。"},{"en":"Continuous quality improvement is a key principle of lean manufacturing.","zh-TW":"持續品質改善是精益製造的關鍵原則。"}]', 'phrasal verb'),
('rate card', '', '', '[{"en":"The media agency provided a rate card for advertising spots.","zh-TW":"媒體代理提供了廣告時段的費率表。"},{"en":"Rate card prices are the starting point for negotiation.","zh-TW":"費率表上的價格是談判的起始點。"}]', 'phrasal verb'),
('recurring costs', '', '', '[{"en":"Software subscriptions and rent are major recurring costs.","zh-TW":"軟件訂閱和租金是主要的經常性成本。"},{"en":"Reducing recurring costs directly improves profitability over time.","zh-TW":"減少經常性成本直接改善了長期盈利能力。"}]', 'phrasal verb'),
('redundancy payment', '', '', '[{"en":"Employees affected by the restructuring received a redundancy payment.","zh-TW":"受重組影響的員工收到了遣散費。"},{"en":"Redundancy payments are calculated based on years of service.","zh-TW":"遣散費根據服務年限計算。"}]', 'phrasal verb'),
('reference rate', '', '', '[{"en":"Variable loans are priced based on a reference rate plus a spread.","zh-TW":"浮動貸款根據參考利率加差價定價。"},{"en":"Changes in the reference rate affect all floating-rate debt instruments.","zh-TW":"參考利率的變化影響了所有浮動利率債務工具。"}]', 'phrasal verb'),
('regional manager', '', '', '[{"en":"The regional manager oversees six branch offices.","zh-TW":"區域經理監管六個分支辦公室。"},{"en":"The regional manager reports directly to the vice president of operations.","zh-TW":"區域經理直接向運營副總裁匯報。"}]', 'phrasal verb'),
('renewal clause', '', '', '[{"en":"The lease included a renewal clause allowing a 3-year extension.","zh-TW":"租約包含了允許延長3年的續約條款。"},{"en":"The client exercised the renewal clause before the contract expired.","zh-TW":"客戶在合約到期前行使了續約條款。"}]', 'phrasal verb'),
('repeat order', '', '', '[{"en":"The product''s quality led to a high rate of repeat orders.","zh-TW":"產品的品質帶來了高比率的重複訂單。"},{"en":"Repeat orders are more cost-effective than acquiring new customers.","zh-TW":"重複訂單比獲取新客戶更具成本效益。"}]', 'phrasal verb'),
('report writing', '', '', '[{"en":"Clear report writing is essential for effective business communication.","zh-TW":"清晰的報告撰寫對於有效的業務溝通至關重要。"},{"en":"Report writing skills are highly valued in consulting and finance roles.","zh-TW":"報告撰寫技能在諮詢和財務職位中備受重視。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('required rate of return', '', '', '[{"en":"The project was approved as its IRR exceeded the required rate of return.","zh-TW":"該項目獲得批准，因為其IRR超過了要求回報率。"},{"en":"The required rate of return reflects both risk and opportunity cost.","zh-TW":"要求回報率反映了風險和機會成本。"}]', 'phrasal verb'),
('reserve ratio', '', '', '[{"en":"The central bank raised the reserve ratio to reduce money supply.","zh-TW":"中央銀行提高了準備金比率以減少貨幣供給。"},{"en":"A lower reserve ratio allows banks to lend more and stimulate growth.","zh-TW":"較低的準備金比率允許銀行多放貸並刺激增長。"}]', 'phrasal verb'),
('reserve requirement', '', '', '[{"en":"Banks adjust lending based on the central bank''s reserve requirements.","zh-TW":"銀行根據中央銀行的準備金規定調整貸款。"},{"en":"Reserve requirements act as a buffer against bank runs.","zh-TW":"準備金規定作為應對銀行擠兌的緩衝。"}]', 'phrasal verb'),
('restructuring plan', '', '', '[{"en":"The board approved a three-year restructuring plan to cut costs.","zh-TW":"董事會批准了為期三年的降成本重組計劃。"},{"en":"A successful restructuring plan can restore profitability.","zh-TW":"成功的重組計劃可以恢復盈利能力。"}]', 'phrasal verb'),
('revenue per employee', '', '', '[{"en":"Revenue per employee increased after the automation initiative.","zh-TW":"自動化計劃後人均收入增加了。"},{"en":"High revenue per employee indicates efficient use of human capital.","zh-TW":"高人均收入表明人力資本使用效率高。"}]', 'phrasal verb'),
('revolving credit', '', '', '[{"en":"The company used revolving credit to manage seasonal inventory needs.","zh-TW":"公司使用循環信貸來管理季節性庫存需求。"},{"en":"Revolving credit provides flexibility for short-term liquidity management.","zh-TW":"循環信貸為短期流動性管理提供了靈活性。"}]', 'phrasal verb'),
('rights issue', '', '', '[{"en":"The company launched a rights issue to raise $50 million.","zh-TW":"公司啟動了供股以籌集5000萬元。"},{"en":"Shareholders who do not participate in a rights issue face dilution.","zh-TW":"未參與供股的股東面臨稀釋。"}]', 'phrasal verb'),
('risk premium', '', '', '[{"en":"Investors demand a higher risk premium for investing in emerging markets.","zh-TW":"投資者要求在新興市場投資有更高的風險溢酬。"},{"en":"The risk premium compensates for uncertainty in projected cash flows.","zh-TW":"風險溢酬補償了預期現金流的不確定性。"}]', 'phrasal verb'),
('rolling average', '', '', '[{"en":"A 12-month rolling average smooths out short-term fluctuations in revenue.","zh-TW":"12個月滾動平均消除了收入的短期波動。"},{"en":"Rolling averages are used in trend analysis and forecasting.","zh-TW":"滾動平均用於趨勢分析和預測。"}]', 'phrasal verb'),
('sales budget', '', '', '[{"en":"The sales budget was increased by 20% for the next fiscal year.","zh-TW":"下一財政年度的銷售預算增加了20%。"},{"en":"A realistic sales budget guides hiring and inventory decisions.","zh-TW":"實際的銷售預算指導了聘用和庫存決策。"}]', 'phrasal verb'),
('sales ledger', '', '', '[{"en":"The accounts team reconciles the sales ledger with bank receipts.","zh-TW":"帳務團隊將銷售分類帳與銀行收款對帳。"},{"en":"An accurate sales ledger is essential for tracking receivables.","zh-TW":"準確的銷售分類帳對於追蹤應收帳款至關重要。"}]', 'phrasal verb'),
('sales quota', '', '', '[{"en":"The sales team achieved 110% of their sales quota for the quarter.","zh-TW":"銷售團隊實現了本季度銷售配額的110%。"},{"en":"Sales quotas are set based on market potential and historical performance.","zh-TW":"銷售配額根據市場潛力和歷史業績設定。"}]', 'phrasal verb'),
('salvage value', '', '', '[{"en":"The plant was depreciated to its estimated salvage value of $10000.","zh-TW":"工廠被折舊到估計殘值10,000元。"},{"en":"A higher salvage value reduces the annual depreciation charge.","zh-TW":"較高的殘值降低了年度折舊費用。"}]', 'phrasal verb'),
('secured debt', '', '', '[{"en":"Secured debt is less risky for lenders because it is backed by assets.","zh-TW":"有擔保債務對貸款方風險較低，因為有資產擔保。"},{"en":"Secured debt holders have priority over unsecured creditors in bankruptcy.","zh-TW":"在破產時，有擔保債務持有人優先於無擔保債權人。"}]', 'phrasal verb'),
('segregation of duties', '', '', '[{"en":"Segregation of duties requires different people to authorize and process payments.","zh-TW":"職責分離要求不同的人授權和處理付款。"},{"en":"Lack of segregation of duties is a major internal control weakness.","zh-TW":"缺乏職責分離是主要的內部控制薄弱環節。"}]', 'phrasal verb'),
('soft loan', '', '', '[{"en":"The government offered soft loans to encourage small business investment.","zh-TW":"政府提供優惠貸款以鼓勵小企業投資。"},{"en":"Soft loans are often used to fund infrastructure in developing countries.","zh-TW":"優惠貸款通常用於在發展中國家為基礎設施融資。"}]', 'phrasal verb'),
('special purpose vehicle', '', '', '[{"en":"The real estate fund used a special purpose vehicle for each property.","zh-TW":"房地產基金為每個物業使用了一個特殊目的公司。"},{"en":"A special purpose vehicle isolates financial risk from the parent company.","zh-TW":"特殊目的公司將財務風險從母公司中隔離出來。"}]', 'phrasal verb'),
('speculative investment', '', '', '[{"en":"The company avoided speculative investments in favor of stable bonds.","zh-TW":"公司避免了投機性投資，轉而選擇穩定的債券。"},{"en":"Speculative investments can generate high returns but also large losses.","zh-TW":"投機性投資可以帶來高回報，但也可能帶來巨大損失。"}]', 'phrasal verb'),
('squeeze margin', '', '', '[{"en":"Retailers had their margins squeezed by rising logistics costs.","zh-TW":"零售商的利潤率因不斷上升的物流成本而受到壓縮。"},{"en":"Intense competition continued to squeeze margins across the sector.","zh-TW":"激烈的競爭繼續壓縮整個行業的利潤率。"}]', 'phrasal verb'),
('start-up costs', '', '', '[{"en":"Total start-up costs for the new outlet were $150000.","zh-TW":"新門市的總啟動成本為15萬元。"},{"en":"Investors typically fund start-up costs in exchange for equity.","zh-TW":"投資者通常通過提供啟動成本換取股權。"}]', 'phrasal verb'),
('straight-line depreciation', '', '', '[{"en":"Straight-line depreciation charges $10000 per year on a $100000 asset.","zh-TW":"直線折舊法對10萬元資產每年計提1萬元折舊。"},{"en":"Straight-line depreciation is simple to apply and widely used.","zh-TW":"直線折舊法簡單易用且廣泛使用。"}]', 'phrasal verb'),
('structural change', '', '', '[{"en":"Digital commerce represents a structural change in retail.","zh-TW":"數位商務代表著零售業的結構性變化。"},{"en":"Structural change often displaces workers who must reskill.","zh-TW":"結構性變化往往使需要重新培訓的工人失業。"}]', 'phrasal verb'),
('surplus cash', '', '', '[{"en":"The company invested surplus cash in short-term government bonds.","zh-TW":"公司將盈餘現金投資於短期政府債券。"},{"en":"Surplus cash can be returned to shareholders through dividends or buybacks.","zh-TW":"盈餘現金可以通過股息或回購的形式返還給股東。"}]', 'phrasal verb'),
('tail risk', '', '', '[{"en":"The portfolio was structured to protect against tail risk scenarios.","zh-TW":"投資組合的結構旨在防範尾部風險情境。"},{"en":"Tail risk events like financial crises are rare but devastating.","zh-TW":"金融危機等尾部風險事件雖罕見但破壞力極強。"}]', 'phrasal verb'),
('tax efficiency', '', '', '[{"en":"The corporate structure was designed for tax efficiency.","zh-TW":"企業結構被設計為稅務效率最優。"},{"en":"Tax efficiency is a key consideration in cross-border investment.","zh-TW":"稅務效率是跨境投資的重要考量因素。"}]', 'phrasal verb'),
('tax loss carryforward', '', '', '[{"en":"The company used a tax loss carryforward to reduce next year''s tax.","zh-TW":"公司使用了虧損結轉來減少明年的稅款。"},{"en":"Tax loss carryforwards can significantly reduce future tax liabilities.","zh-TW":"虧損結轉可以顯著降低未來的稅務負債。"}]', 'phrasal verb'),
('term loan', '', '', '[{"en":"The company took a five-year term loan to finance the factory expansion.","zh-TW":"公司獲得了五年定期貸款以資助工廠擴張。"},{"en":"Term loan interest rates can be fixed or variable.","zh-TW":"定期貸款利率可以是固定或浮動的。"}]', 'phrasal verb'),
('timely delivery', '', '', '[{"en":"Timely delivery is a key performance metric for logistics providers.","zh-TW":"及時交付是物流供應商的關鍵績效指標。"},{"en":"Failure to ensure timely delivery may trigger penalties under the contract.","zh-TW":"未能確保及時交付可能觸發合約下的罰款。"}]', 'phrasal verb'),
('title deed', '', '', '[{"en":"The title deed was transferred to the buyer after full payment.","zh-TW":"全額付款後，產權契據轉讓給了買方。"},{"en":"A bank holds the title deed as security for a mortgage.","zh-TW":"銀行持有產權契據作為抵押貸款的擔保。"}]', 'phrasal verb'),
('top-line growth', '', '', '[{"en":"The company achieved 20% top-line growth driven by new markets.","zh-TW":"公司依靠新市場實現了20%的頂線增長。"},{"en":"Top-line growth does not always translate into bottom-line improvement.","zh-TW":"頂線增長並不總是轉化為淨利潤的改善。"}]', 'phrasal verb'),
('trade barrier', '', '', '[{"en":"Tariffs and quotas are common forms of trade barriers.","zh-TW":"關稅和配額是常見形式的貿易壁壘。"},{"en":"Free trade agreements aim to reduce trade barriers between signatories.","zh-TW":"自由貿易協議旨在減少簽署方之間的貿易壁壘。"}]', 'phrasal verb'),
('transfer of ownership', '', '', '[{"en":"The transfer of ownership was finalized at the notary office.","zh-TW":"所有權轉讓在公證處完成了。"},{"en":"A transfer of ownership requires proper documentation and registration.","zh-TW":"所有權轉讓需要適當的文件和登記。"}]', 'phrasal verb'),
('treasury stock', '', '', '[{"en":"The company holds treasury stock purchased during the buyback program.","zh-TW":"公司持有在回購計劃期間購買的庫藏股。"},{"en":"Treasury stock reduces the number of shares outstanding in the market.","zh-TW":"庫藏股減少了市場上流通的股份數量。"}]', 'phrasal verb'),
('unauthorized access', '', '', '[{"en":"Unauthorized access to financial systems was detected and blocked.","zh-TW":"對財務系統的未經授權存取被檢測並阻止了。"},{"en":"Multi-factor authentication reduces the risk of unauthorized access.","zh-TW":"多因素驗證降低了未經授權存取的風險。"}]', 'phrasal verb'),
('umbrella policy', '', '', '[{"en":"The company purchased an umbrella policy to cover large liability claims.","zh-TW":"公司購買了綜合責任保險以涵蓋大額責任索賠。"},{"en":"An umbrella policy provides extra coverage beyond standard insurance limits.","zh-TW":"綜合責任保險在標準保險限額之外提供了額外保障。"}]', 'phrasal verb'),
('underwriting risk', '', '', '[{"en":"The bank reduced underwriting risk by syndicating the bond issuance.","zh-TW":"銀行通過聯合發行債券降低了承銷風險。"},{"en":"Underwriting risk is higher in volatile markets with uncertain demand.","zh-TW":"在需求不確定的波動市場中，承銷風險較高。"}]', 'phrasal verb'),
('unit price', '', '', '[{"en":"The unit price was reduced to $8 for orders above 1000 pieces.","zh-TW":"訂購超過1000件時單價降至8元。"},{"en":"A lower unit price increases competitiveness but requires higher volume.","zh-TW":"較低的單價提高了競爭力，但需要更高的銷量。"}]', 'phrasal verb'),
('unsystematic risk', '', '', '[{"en":"Diversifying across sectors reduces unsystematic risk in a portfolio.","zh-TW":"跨行業多元化降低了投資組合中的非系統性風險。"},{"en":"Unsystematic risk includes management changes and product recalls.","zh-TW":"非系統性風險包括管理層變動和產品召回。"}]', 'phrasal verb'),
('upselling technique', '', '', '[{"en":"Training staff in upselling techniques increased average order values by 18%.","zh-TW":"培訓員工掌握追加銷售技巧使平均訂單金額增加了18%。"},{"en":"An effective upselling technique focuses on customer benefits, not price.","zh-TW":"有效的追加銷售技巧側重於客戶效益而非價格。"}]', 'phrasal verb'),
('value-added services', '', '', '[{"en":"The logistics company offered value-added services like custom labeling.","zh-TW":"物流公司提供了包括定制標籤在內的增值服務。"},{"en":"Value-added services differentiate a business from low-cost competitors.","zh-TW":"增值服務使業務與低成本競爭對手區分開來。"}]', 'phrasal verb'),
('vendor due diligence', '', '', '[{"en":"The seller prepared a vendor due diligence report before listing the company.","zh-TW":"賣方在出售公司前準備了供應商盡職調查報告。"},{"en":"Vendor due diligence speeds up the sale process by providing ready information.","zh-TW":"供應商盡職調查通過提供現成信息加快了銷售流程。"}]', 'phrasal verb'),
('vesting period', '', '', '[{"en":"Employees must complete a three-year vesting period before claiming shares.","zh-TW":"員工必須完成三年歸屬期才能申領股份。"},{"en":"A longer vesting period encourages employee retention.","zh-TW":"較長的歸屬期鼓勵了員工留任。"}]', 'phrasal verb'),
('wage freeze', '', '', '[{"en":"A wage freeze was imposed across the organization to reduce costs.","zh-TW":"為降低成本在全組織範圍內實施了工資凍結。"},{"en":"After the wage freeze, staff received a 5% catch-up increase.","zh-TW":"工資凍結結束後，員工獲得了5%的補償性加薪。"}]', 'phrasal verb'),
('white paper', '', '', '[{"en":"The company published a white paper on AI in supply chain management.","zh-TW":"公司發布了一份關於人工智慧在供應鏈管理中的白皮書。"},{"en":"A white paper establishes thought leadership and educates potential clients.","zh-TW":"白皮書確立了思想領導地位並教育了潛在客戶。"}]', 'phrasal verb'),
('withholding tax', '', '', '[{"en":"Dividends paid to non-residents are subject to withholding tax.","zh-TW":"支付給非居民的股息須繳納預扣稅。"},{"en":"The withholding tax rate on interest payments is 15%.","zh-TW":"利息付款的預扣稅率為15%。"}]', 'phrasal verb'),
('working capital ratio', '', '', '[{"en":"A working capital ratio above 1 indicates the company can cover short-term debt.","zh-TW":"高於1的營運資金比率表明公司可以償還短期債務。"},{"en":"The CFO monitored the working capital ratio to manage liquidity risk.","zh-TW":"財務長監控營運資金比率以管理流動性風險。"}]', 'phrasal verb'),
('working interest', '', '', '[{"en":"The company sold its 30% working interest in the oil field.","zh-TW":"公司出售了其在油田中30%的作業利益。"},{"en":"A working interest holder bears both the costs and benefits of production.","zh-TW":"作業利益持有人承擔生產的成本和收益。"}]', 'phrasal verb'),
('zone pricing', '', '', '[{"en":"The logistics company uses zone pricing based on delivery distance.","zh-TW":"物流公司根據交貨距離使用區域定價。"},{"en":"Zone pricing reflects the actual cost of serving different geographic areas.","zh-TW":"區域定價反映了服務不同地理區域的實際成本。"}]', 'phrasal verb'),
('account payable', '', '', '[{"en":"The account payable was due within 30 days of the invoice date.","zh-TW":"應付帳款在發票日期後30天到期。"},{"en":"Managing account payable terms improves working capital efficiency.","zh-TW":"管理應付帳款條款提高了營運資金效率。"}]', 'phrasal verb'),
('adjusting entry', '', '', '[{"en":"Adjusting entries ensure that revenues and expenses are properly matched.","zh-TW":"調整分錄確保收入和費用的適當配比。"},{"en":"The accountant made adjusting entries to correct the monthly accounts.","zh-TW":"會計師進行了調整分錄以修正月度帳目。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('advance notice', '', '', '[{"en":"The contract requires 60 days advance notice for termination.","zh-TW":"合約要求提前60天通知終止。"},{"en":"Employees must give advance notice before taking extended leave.","zh-TW":"員工在請長假前必須提前通知。"}]', 'phrasal verb'),
('adverse conditions', '', '', '[{"en":"Sales declined due to adverse market conditions during the quarter.","zh-TW":"由於本季度不利的市場條件，銷售額下降了。"},{"en":"The company showed resilience in the face of adverse economic conditions.","zh-TW":"公司在面對不利的經濟條件時表現出了韌性。"}]', 'phrasal verb'),
('after-tax profit', '', '', '[{"en":"After-tax profit rose by 22% due to improved cost control.","zh-TW":"由於成本控制改善，稅後利潤增長了22%。"},{"en":"Investors compare after-tax profit margins across competitors.","zh-TW":"投資者比較競爭對手之間的稅後利潤率。"}]', 'phrasal verb'),
('agreed terms', '', '', '[{"en":"The deal was completed on agreed terms satisfactory to both parties.","zh-TW":"交易在雙方滿意的商定條款下完成了。"},{"en":"Any deviation from agreed terms must be documented in writing.","zh-TW":"對商定條款的任何偏差都必須以書面形式記錄。"}]', 'phrasal verb'),
('allocation method', '', '', '[{"en":"The company uses activity-based allocation methods for overhead costs.","zh-TW":"公司對間接費用使用基於活動的分配方法。"},{"en":"Choosing the right allocation method is critical for accurate pricing.","zh-TW":"選擇正確的分配方法對於準確定價至關重要。"}]', 'phrasal verb'),
('ancillary cost', '', '', '[{"en":"Freight, customs, and insurance are ancillary costs of importing.","zh-TW":"貨運、海關和保險費是進口的附帶費用。"},{"en":"Ancillary costs can significantly increase the total project expenditure.","zh-TW":"附帶費用可能會顯著增加項目的總支出。"}]', 'phrasal verb'),
('applicable law', '', '', '[{"en":"The contract is governed by and construed in accordance with applicable law.","zh-TW":"合約受適用法律管轄並依其解釋。"},{"en":"Both parties agreed that applicable law would be English law.","zh-TW":"雙方同意適用法律為英國法律。"}]', 'phrasal verb'),
('approval process', '', '', '[{"en":"All capital expenditures must go through the approval process.","zh-TW":"所有資本支出必須通過審批流程。"},{"en":"Streamlining the approval process reduced decision-making time by half.","zh-TW":"簡化審批流程將決策時間縮短了一半。"}]', 'phrasal verb'),
('arbitration agreement', '', '', '[{"en":"The parties entered an arbitration agreement to avoid costly litigation.","zh-TW":"雙方簽訂了仲裁協議以避免代價高昂的訴訟。"},{"en":"An arbitration agreement specifies the governing rules and venue.","zh-TW":"仲裁協議規定了管轄規則和地點。"}]', 'phrasal verb'),
('articles of association', '', '', '[{"en":"The articles of association define voting rights and board powers.","zh-TW":"公司章程規定了投票權和董事會權力。"},{"en":"Changes to the articles of association require shareholder approval.","zh-TW":"對公司章程的修改需要股東批准。"}]', 'phrasal verb'),
('asset class', '', '', '[{"en":"Bonds and equities are distinct asset classes with different risk profiles.","zh-TW":"債券和股票是具有不同風險特徵的不同資產類別。"},{"en":"Portfolio managers allocate capital across multiple asset classes.","zh-TW":"投資組合管理人在多種資產類別中分配資本。"}]', 'phrasal verb'),
('asset register', '', '', '[{"en":"The asset register must be updated whenever assets are purchased or disposed of.","zh-TW":"每次購買或處置資產時，必須更新資產登記冊。"},{"en":"An accurate asset register supports insurance coverage and depreciation.","zh-TW":"準確的資產登記冊支持保險保障和折舊計算。"}]', 'phrasal verb'),
('asset valuation', '', '', '[{"en":"An independent asset valuation was required for the merger.","zh-TW":"合併需要獨立的資產評估。"},{"en":"Asset valuation methods include market value and replacement cost.","zh-TW":"資產評估方法包括市場價值和重置成本。"}]', 'phrasal verb'),
('assignment of contract', '', '', '[{"en":"An assignment of contract clause requires prior written consent.","zh-TW":"合約轉讓條款需要事先書面同意。"},{"en":"The assignment of contract was approved by all parties involved.","zh-TW":"所有相關各方批准了合約轉讓。"}]', 'phrasal verb'),
('associated costs', '', '', '[{"en":"The project''s associated costs exceeded the initial estimate by 20%.","zh-TW":"項目的相關成本超出了初始估計20%。"},{"en":"All associated costs were disclosed in the financial summary.","zh-TW":"所有相關成本均在財務摘要中披露了。"}]', 'phrasal verb'),
('bargaining power', '', '', '[{"en":"Large retailers have significant bargaining power over their suppliers.","zh-TW":"大型零售商對其供應商有顯著的議價能力。"},{"en":"Consolidating purchases improves a buyer''s bargaining power.","zh-TW":"整合採購提高了買家的議價能力。"}]', 'phrasal verb'),
('benchmark interest rate', '', '', '[{"en":"The central bank raised the benchmark interest rate to curb inflation.","zh-TW":"中央銀行提高了基準利率以抑制通貨膨脹。"},{"en":"Lending rates are typically set above the benchmark interest rate.","zh-TW":"貸款利率通常設定在基準利率之上。"}]', 'phrasal verb'),
('binding contract', '', '', '[{"en":"Both parties signed a binding contract specifying delivery deadlines.","zh-TW":"雙方簽署了一份規定交貨截止日期的具有約束力的合約。"},{"en":"A binding contract requires consideration, capacity, and mutual consent.","zh-TW":"具有約束力的合約需要代價、能力和雙方同意。"}]', 'phrasal verb'),
('bond rating', '', '', '[{"en":"The bond''s rating was downgraded to BB due to weakening earnings.","zh-TW":"由於盈利減弱，債券評級被下調至BB。"},{"en":"A higher bond rating means lower borrowing costs for the issuer.","zh-TW":"較高的債券評級意味著發行人的借貸成本較低。"}]', 'phrasal verb'),
('breach of duty', '', '', '[{"en":"The manager''s actions constituted a clear breach of duty.","zh-TW":"該管理者的行為構成了明顯的違反職責。"},{"en":"Directors can be held liable for breach of duty to shareholders.","zh-TW":"董事可能因違反對股東的職責而承擔責任。"}]', 'phrasal verb'),
('business ethics', '', '', '[{"en":"A strong culture of business ethics reduces legal and reputational risk.","zh-TW":"強烈的商業道德文化降低了法律和聲譽風險。"},{"en":"Business ethics training is mandatory for all new employees.","zh-TW":"商業道德培訓對所有新員工都是強制性的。"}]', 'phrasal verb'),
('capitalization rate', '', '', '[{"en":"A lower capitalization rate suggests higher property value and lower risk.","zh-TW":"較低的資本化率表明物業價值較高且風險較低。"},{"en":"Investors use the capitalization rate to compare real estate returns.","zh-TW":"投資者使用資本化率比較房地產回報。"}]', 'phrasal verb'),
('carriage paid', '', '', '[{"en":"The goods were delivered carriage paid to the buyer''s warehouse.","zh-TW":"貨物以運費已付的方式交付到買方倉庫。"},{"en":"Carriage paid terms shift delivery risk at the first carrier handover.","zh-TW":"運費已付條款在第一個承運人移交時轉移交付風險。"}]', 'phrasal verb'),
('cash disbursement', '', '', '[{"en":"All cash disbursements must be approved by the finance manager.","zh-TW":"所有現金支出必須由財務經理批准。"},{"en":"The cash disbursement journal tracks all outgoing payments chronologically.","zh-TW":"現金支出日記帳按時間順序追蹤所有外出付款。"}]', 'phrasal verb'),
('ceiling price', '', '', '[{"en":"The government set a ceiling price on essential food items.","zh-TW":"政府對基本食品設定了價格上限。"},{"en":"Ceiling prices protect consumers but may lead to supply shortages.","zh-TW":"價格上限保護消費者但可能導致供應短缺。"}]', 'phrasal verb'),
('certified check', '', '', '[{"en":"The landlord required a certified check for the security deposit.","zh-TW":"房東要求用保付支票支付押金。"},{"en":"A certified check reduces the risk of a payment being dishonoured.","zh-TW":"保付支票降低了付款被拒絕的風險。"}]', 'phrasal verb'),
('check register', '', '', '[{"en":"The bookkeeper updated the check register after every payment.","zh-TW":"簿記員在每次付款後更新了支票登記簿。"},{"en":"A check register helps detect unauthorized or duplicate payments.","zh-TW":"支票登記簿有助於發現未經授權或重複的付款。"}]', 'phrasal verb'),
('chief compliance officer', '', '', '[{"en":"The chief compliance officer implemented a company-wide ethics training program.","zh-TW":"首席合規官實施了全公司道德培訓計劃。"},{"en":"Regulators require a chief compliance officer for financial institutions.","zh-TW":"監管機構要求金融機構設立首席合規官。"}]', 'phrasal verb'),
('closing entry', '', '', '[{"en":"Closing entries reset temporary accounts to zero for the next period.","zh-TW":"結帳分錄將臨時帳戶重置為零以準備下一期。"},{"en":"The closing entry transferred net income to the retained earnings account.","zh-TW":"結帳分錄將淨利潤轉入留存收益帳戶。"}]', 'phrasal verb'),
('commodity market', '', '', '[{"en":"Oil prices fell sharply on the commodity market yesterday.","zh-TW":"大宗商品市場的石油價格昨天大幅下跌。"},{"en":"Agricultural exporters are highly exposed to commodity market fluctuations.","zh-TW":"農業出口商對大宗商品市場波動的敞口很高。"}]', 'phrasal verb'),
('compensatory damages', '', '', '[{"en":"The court awarded compensatory damages of $200,000 for lost profits.","zh-TW":"法院判給了20萬元的補償性損害賠償以補償利潤損失。"},{"en":"Compensatory damages aim to make the injured party whole.","zh-TW":"補償性損害賠償旨在使受害方恢復原狀。"}]', 'phrasal verb'),
('concurrent liability', '', '', '[{"en":"Both the contractor and subcontractor bore concurrent liability for the damage.","zh-TW":"承包商和分包商對損失承擔連帶責任。"},{"en":"Concurrent liability issues arise when multiple defendants cause the same harm.","zh-TW":"多名被告造成相同損害時會出現連帶責任問題。"}]', 'phrasal verb'),
('confidentiality clause', '', '', '[{"en":"A confidentiality clause protects trade secrets during negotiations.","zh-TW":"保密條款在談判期間保護商業機密。"},{"en":"Breach of the confidentiality clause may result in significant penalties.","zh-TW":"違反保密條款可能導致重大罰款。"}]', 'phrasal verb'),
('convertible note', '', '', '[{"en":"The startup raised $2 million through convertible notes from angel investors.","zh-TW":"該初創公司通過天使投資者的可轉換票據籌集了200萬元。"},{"en":"Convertible notes defer valuation until the next equity financing round.","zh-TW":"可轉換票據將估值推遲到下一輪股權融資。"}]', 'phrasal verb'),
('core business', '', '', '[{"en":"The company divested non-core assets to focus on its core business.","zh-TW":"公司剝離了非核心資產以專注於其核心業務。"},{"en":"Strengthening core business operations is the priority for this fiscal year.","zh-TW":"加強核心業務運作是本財年的優先事項。"}]', 'phrasal verb'),
('cost-benefit ratio', '', '', '[{"en":"A cost-benefit ratio below 1 indicates expected benefits exceed costs.","zh-TW":"低於1的成本效益比表明預期效益超過了成本。"},{"en":"The project was approved based on a strong cost-benefit ratio.","zh-TW":"項目基於強勁的成本效益比獲得了批准。"}]', 'phrasal verb'),
('credit worthiness', '', '', '[{"en":"Banks evaluate creditworthiness before approving a business loan.","zh-TW":"銀行在批准商業貸款前評估信用度。"},{"en":"A strong credit history improves a company''s creditworthiness rating.","zh-TW":"強大的信用歷史改善了公司的信用度評級。"}]', 'phrasal verb'),
('customs broker', '', '', '[{"en":"The customs broker ensured all documentation met import regulations.","zh-TW":"報關行確保所有文件符合進口法規。"},{"en":"Using a customs broker reduces clearance delays and compliance errors.","zh-TW":"使用報關行減少了清關延誤和合規錯誤。"}]', 'phrasal verb'),
('delivery duty paid', '', '', '[{"en":"Under delivery duty paid, the seller handles customs clearance at destination.","zh-TW":"在完稅後交貨條件下，賣方負責目的地的海關清關。"},{"en":"Buyers often prefer delivery duty paid for the simplicity it offers.","zh-TW":"買方通常更喜歡完稅後交貨，因為它提供的便利性。"}]', 'phrasal verb'),
('dividend yield', '', '', '[{"en":"Investors seeking income focus on stocks with a high dividend yield.","zh-TW":"尋求收入的投資者專注於高股息殖利率的股票。"},{"en":"The dividend yield fell as the company''s share price rose rapidly.","zh-TW":"隨著公司股價快速上漲，股息殖利率下降了。"}]', 'phrasal verb'),
('dry run', '', '', '[{"en":"The team conducted a dry run of the system migration over the weekend.","zh-TW":"團隊在週末進行了系統遷移的演習。"},{"en":"A dry run of the product launch revealed several communication gaps.","zh-TW":"產品發布的預演揭示了幾個溝通空白。"}]', 'phrasal verb'),
('earnings call', '', '', '[{"en":"Management highlighted strong revenue growth during the earnings call.","zh-TW":"管理層在業績發布電話會議上強調了強勁的收入增長。"},{"en":"Analysts submitted questions about margins during the quarterly earnings call.","zh-TW":"分析師在季度業績發布電話會議上提交了有關利潤率的問題。"}]', 'phrasal verb'),
('earnings release', '', '', '[{"en":"The earnings release showed a 15% increase in quarterly net income.","zh-TW":"業績公告顯示季度淨利潤增加了15%。"},{"en":"Investors study the earnings release for signs of operational improvement.","zh-TW":"投資者研究業績公告以尋找運營改善的跡象。"}]', 'phrasal verb'),
('ebitda margin', '', '', '[{"en":"The company reported an EBITDA margin of 22% for the fiscal year.","zh-TW":"公司報告了本財年22%的息稅折舊攤銷前利潤率。"},{"en":"Investors use EBITDA margin to compare profitability across companies.","zh-TW":"投資者使用息稅折舊攤銷前利潤率比較各公司的盈利能力。"}]', 'phrasal verb'),
('environmental compliance', '', '', '[{"en":"The plant was fined for failing to meet environmental compliance standards.","zh-TW":"該工廠因未能達到環境合規標準而被罰款。"},{"en":"Regular audits are conducted to verify environmental compliance.","zh-TW":"定期審計用於驗證環境合規性。"}]', 'phrasal verb'),
('escrow agent', '', '', '[{"en":"The escrow agent released the funds after the contract conditions were satisfied.","zh-TW":"在合約條件得到滿足後，託管代理人釋放了資金。"},{"en":"An escrow agent provides security to both buyer and seller in a transaction.","zh-TW":"託管代理人在交易中為買賣雙方提供保障。"}]', 'phrasal verb'),
('excise duty', '', '', '[{"en":"Excise duty on alcohol was increased in the annual budget.","zh-TW":"消費稅在年度預算中提高了對酒精的稅率。"},{"en":"Importers must pay excise duty before goods are released from customs.","zh-TW":"進口商必須在貨物從海關放行前繳納消費稅。"}]', 'phrasal verb'),
('financial forecast', '', '', '[{"en":"The financial forecast predicted revenue growth of 12% next year.","zh-TW":"財務預測預計明年收入增長12%。"},{"en":"Inaccurate financial forecasts can lead to poor resource allocation decisions.","zh-TW":"不準確的財務預測可能導致資源配置決策失誤。"}]', 'phrasal verb'),
('financial ratio', '', '', '[{"en":"Key financial ratios are used to benchmark performance against industry peers.","zh-TW":"關鍵財務比率用於基準化與同行業企業的績效。"},{"en":"Analysts compute multiple financial ratios before making investment recommendations.","zh-TW":"分析師在提出投資建議之前計算多種財務比率。"}]', 'phrasal verb'),
('functional currency', '', '', '[{"en":"The company''s functional currency is the US dollar for all reporting purposes.","zh-TW":"公司的功能貨幣在所有報告目的中為美元。"},{"en":"Transactions in other currencies are translated at the functional currency rate.","zh-TW":"其他貨幣的交易按功能貨幣匯率換算。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('fund manager', '', '', '[{"en":"The fund manager achieved returns 3% above the benchmark index.","zh-TW":"基金經理取得了高出基準指數3%的回報。"},{"en":"Investors evaluate a fund manager''s track record before committing capital.","zh-TW":"投資者在投入資金前評估基金經理的業績記錄。"}]', 'phrasal verb'),
('grievance procedure', '', '', '[{"en":"Employees must follow the grievance procedure before escalating to external bodies.","zh-TW":"員工在上升至外部機構之前必須遵循申訴程序。"},{"en":"The HR team handled the complaint through the standard grievance procedure.","zh-TW":"HR團隊通過標準申訴程序處理了投訴。"}]', 'phrasal verb'),
('guarantee fund', '', '', '[{"en":"The government established a guarantee fund to protect bank depositors.","zh-TW":"政府建立了一個保障基金以保護銀行存款人。"},{"en":"Exporters benefit from a guarantee fund that covers buyer payment defaults.","zh-TW":"出口商受益於涵蓋買方付款違約的擔保基金。"}]', 'phrasal verb'),
('high-yield bond', '', '', '[{"en":"High-yield bonds offer higher returns but carry greater default risk.","zh-TW":"高收益債券提供較高回報，但承擔較大的違約風險。"},{"en":"The fund allocated 15% of its portfolio to high-yield bonds.","zh-TW":"基金將其投資組合的15%分配到了高收益債券。"}]', 'phrasal verb'),
('holding period', '', '', '[{"en":"Capital gains tax rates depend on the holding period of the asset.","zh-TW":"資本利得稅率取決於資產的持有期間。"},{"en":"A longer holding period reduces trading costs and improves long-term returns.","zh-TW":"較長的持有期間降低了交易成本並改善了長期回報。"}]', 'phrasal verb'),
('indemnity clause', '', '', '[{"en":"The indemnity clause required the supplier to cover third-party claims.","zh-TW":"賠償條款要求供應商承擔第三方索賠。"},{"en":"An indemnity clause protects the service provider against consequential damages.","zh-TW":"賠償條款保護服務提供商免受間接損害。"}]', 'phrasal verb'),
('index fund', '', '', '[{"en":"Index funds offer broad market exposure at lower fees than active funds.","zh-TW":"指數基金以低於主動管理基金的費用提供廣泛的市場敞口。"},{"en":"Long-term investors often prefer index funds for their consistent returns.","zh-TW":"長期投資者通常偏好指數基金，因為其一致的回報。"}]', 'phrasal verb'),
('inflation rate', '', '', '[{"en":"Central banks raise interest rates to control a rising inflation rate.","zh-TW":"中央銀行提高利率以控制不斷上升的通貨膨脹率。"},{"en":"An inflation rate above 5% erodes consumer purchasing power.","zh-TW":"超過5%的通貨膨脹率侵蝕了消費者的購買力。"}]', 'phrasal verb'),
('job costing', '', '', '[{"en":"Job costing allowed the firm to identify which projects were most profitable.","zh-TW":"工作成本核算使公司能夠識別哪些項目最盈利。"},{"en":"Construction companies rely on job costing to manage project budgets.","zh-TW":"建築公司依賴工作成本核算來管理項目預算。"}]', 'phrasal verb'),
('joint and several liability', '', '', '[{"en":"Under joint and several liability, any defendant can be sued for the full loss.","zh-TW":"在連帶及各自責任下，任何被告都可以被起訴承擔全部損失。"},{"en":"Lenders prefer joint and several liability to reduce default risk.","zh-TW":"貸款機構更喜歡連帶及各自責任以降低違約風險。"}]', 'phrasal verb'),
('labour turnover', '', '', '[{"en":"High labour turnover increases recruitment and training costs.","zh-TW":"高勞動力流動率增加了招募和培訓成本。"},{"en":"Flexible work policies significantly reduced the company''s labour turnover.","zh-TW":"彈性工作政策顯著降低了公司的勞動力流動率。"}]', 'phrasal verb'),
('leasehold improvement', '', '', '[{"en":"The company spent $300,000 on leasehold improvements to fit out the new office.","zh-TW":"公司花費了30萬元對新辦公室進行了租賃改良。"},{"en":"Leasehold improvements are amortized over the lease term or useful life.","zh-TW":"租賃改良在租賃期或有效使用年限內進行攤銷。"}]', 'phrasal verb'),
('leverage ratio', '', '', '[{"en":"A high leverage ratio means the company is heavily dependent on debt financing.","zh-TW":"高槓桿比率意味著公司嚴重依賴債務融資。"},{"en":"Regulators monitor banks'' leverage ratios to ensure financial stability.","zh-TW":"監管機構監控銀行的槓桿比率以確保金融穩定。"}]', 'phrasal verb'),
('long-term liability', '', '', '[{"en":"Long-term liabilities include bonds payable and pension obligations.","zh-TW":"長期負債包括應付債券和養老金義務。"},{"en":"Investors assess long-term liabilities when evaluating a company''s solvency.","zh-TW":"投資者在評估公司的償付能力時評估長期負債。"}]', 'phrasal verb'),
('lump-sum payment', '', '', '[{"en":"The employee chose a lump-sum payment instead of monthly pension installments.","zh-TW":"員工選擇了一次性付款而不是每月養老金分期付款。"},{"en":"The contract was settled with a lump-sum payment of $500,000.","zh-TW":"合約以50萬元的一次性付款了結了。"}]', 'phrasal verb'),
('master service agreement', '', '', '[{"en":"The master service agreement covered all future projects between the two firms.","zh-TW":"主服務協議涵蓋了兩家公司之間所有未來的項目。"},{"en":"Individual project scopes are added as appendices to the master service agreement.","zh-TW":"個別項目範圍作為附件添加到主服務協議中。"}]', 'phrasal verb'),
('merger arbitrage', '', '', '[{"en":"Merger arbitrage funds profit from the spread between offer and market prices.","zh-TW":"合併套利基金從要約價格和市場價格之間的差價中獲利。"},{"en":"Merger arbitrage requires careful analysis of deal completion probabilities.","zh-TW":"合併套利需要對交易完成概率進行仔細分析。"}]', 'phrasal verb'),
('mortgage backed security', '', '', '[{"en":"Banks package mortgages into mortgage backed securities to free up capital.","zh-TW":"銀行將抵押貸款打包成抵押擔保證券以釋放資本。"},{"en":"The financial crisis was linked to high-risk mortgage backed securities.","zh-TW":"金融危機與高風險抵押擔保證券有關。"}]', 'phrasal verb'),
('net asset value', '', '', '[{"en":"The fund''s net asset value increased by 8% over the quarter.","zh-TW":"基金的淨資產價值在本季度增加了8%。"},{"en":"Mutual fund units are priced based on daily net asset value.","zh-TW":"共同基金單位根據每日淨資產價值定價。"}]', 'phrasal verb'),
('non-recurring charge', '', '', '[{"en":"The company reported a non-recurring charge for restructuring costs.","zh-TW":"公司報告了一項重組費用的非經常性費用。"},{"en":"Non-recurring charges are excluded from adjusted earnings calculations.","zh-TW":"非經常性費用從調整後盈利計算中排除。"}]', 'phrasal verb'),
('operating expense', '', '', '[{"en":"Rising operating expenses squeezed the company''s profit margins.","zh-TW":"不斷上升的運營費用壓縮了公司的利潤率。"},{"en":"Management set a target to reduce operating expenses by 10%.","zh-TW":"管理層設定了將運營費用降低10%的目標。"}]', 'phrasal verb'),
('pro forma invoice', '', '', '[{"en":"The buyer requested a pro forma invoice to arrange advance payment.","zh-TW":"買方請求了一份形式發票以安排預付款。"},{"en":"A pro forma invoice is not a demand for payment but a price estimate.","zh-TW":"形式發票不是付款要求，而是價格估算。"}]', 'phrasal verb'),
('promissory note', '', '', '[{"en":"The borrower signed a promissory note committing to repay the loan.","zh-TW":"借款人簽署了一份承諾償還貸款的本票。"},{"en":"A promissory note is a negotiable instrument transferable to third parties.","zh-TW":"本票是可轉讓給第三方的流通票據。"}]', 'phrasal verb'),
('qualified opinion', '', '', '[{"en":"The auditor issued a qualified opinion due to limitations in inventory verification.","zh-TW":"審計師由於庫存核查的限制發出了保留意見。"},{"en":"A qualified opinion does not mean the financial statements are materially misstated.","zh-TW":"保留意見並不意味著財務報表存在重大錯誤陳述。"}]', 'phrasal verb'),
('regulatory authority', '', '', '[{"en":"The drug required approval from the regulatory authority before launch.","zh-TW":"藥物在上市之前需要監管機構的批准。"},{"en":"Violations may result in sanctions imposed by the regulatory authority.","zh-TW":"違規行為可能導致監管機構實施制裁。"}]', 'phrasal verb'),
('risk management framework', '', '', '[{"en":"The company implemented an enterprise risk management framework last year.","zh-TW":"公司去年實施了企業風險管理框架。"},{"en":"A robust risk management framework is required by financial regulators.","zh-TW":"金融監管機構要求具有健全的風險管理框架。"}]', 'phrasal verb'),
('royalty payment', '', '', '[{"en":"The inventor receives annual royalty payments from the licensing deal.","zh-TW":"發明人從授權協議中獲得年度版稅。"},{"en":"Royalty payments are calculated as a percentage of licensed product sales.","zh-TW":"版稅根據授權產品銷售額的百分比計算。"}]', 'phrasal verb'),
('shareholder equity', '', '', '[{"en":"Retained earnings are the main driver of growing shareholder equity.","zh-TW":"留存收益是股東權益增長的主要驅動力。"},{"en":"Shareholder equity declined after the share buyback reduced reserves.","zh-TW":"在股票回購減少了儲備後，股東權益下降了。"}]', 'phrasal verb'),
('shipping manifest', '', '', '[{"en":"The shipping manifest must be submitted to customs before departure.","zh-TW":"裝貨清單必須在出發前提交給海關。"},{"en":"Discrepancies between the shipping manifest and actual cargo can delay clearance.","zh-TW":"裝貨清單與實際貨物之間的差異可能延遲清關。"}]', 'phrasal verb'),
('spot rate', '', '', '[{"en":"The invoice was converted at the spot rate on the payment date.","zh-TW":"發票在付款日以即期匯率換算。"},{"en":"Currency hedges allow companies to avoid spot rate volatility.","zh-TW":"貨幣對沖允許企業避免即期匯率波動。"}]', 'phrasal verb'),
('takeover bid', '', '', '[{"en":"The board rejected the hostile takeover bid as undervaluing the company.","zh-TW":"董事會以低估公司價值為由拒絕了敵意收購要約。"},{"en":"A friendly takeover bid results in agreed terms between both boards.","zh-TW":"友好的收購要約在雙方董事會之間達成了商定條款。"}]', 'phrasal verb'),
('trading volume', '', '', '[{"en":"Heavy trading volume accompanied the sharp rise in the stock price.","zh-TW":"大量的交易量伴隨著股價的急劇上漲。"},{"en":"Low trading volume can make it difficult to buy or sell a position quickly.","zh-TW":"低交易量可能使快速買入或賣出倉位變得困難。"}]', 'phrasal verb'),
('trust account', '', '', '[{"en":"Client funds are held in a separate trust account for legal protection.","zh-TW":"客戶資金保存在獨立的信託帳戶中以提供法律保護。"},{"en":"Real estate agents are legally required to use a trust account for deposits.","zh-TW":"房地產代理依法要求將訂金存入信託帳戶。"}]', 'phrasal verb'),
('upfront payment', '', '', '[{"en":"An upfront payment of 30% was required before production started.","zh-TW":"在開始生產之前需要30%的預付款。"},{"en":"Freelancers often request an upfront payment to secure new projects.","zh-TW":"自由工作者通常要求預付款以確保新項目。"}]', 'phrasal verb'),
('void contract', '', '', '[{"en":"A contract signed under duress may be declared a void contract.","zh-TW":"在脅迫下簽署的合約可能被宣布為無效合約。"},{"en":"Fraud in the formation of an agreement renders it a void contract.","zh-TW":"協議簽訂過程中的欺詐行為使其成為無效合約。"}]', 'phrasal verb'),
('window dressing', '', '', '[{"en":"Some companies engage in window dressing before the annual report deadline.","zh-TW":"某些公司在年報截止日期前進行表面文章。"},{"en":"Window dressing distorts the true picture of a company''s financial health.","zh-TW":"表面文章歪曲了公司財務狀況的真實面貌。"}]', 'phrasal verb'),
('yield to maturity', '', '', '[{"en":"The bond''s yield to maturity of 5% exceeds the current coupon rate.","zh-TW":"債券的5%到期殖利率超過了當前票息率。"},{"en":"Investors compare yield to maturity when choosing between bonds.","zh-TW":"投資者在選擇債券時比較到期殖利率。"}]', 'phrasal verb'),
('above the line', '', '', '[{"en":"Above-the-line advertising includes TV, radio, and national press campaigns.","zh-TW":"線上廣告包括電視、廣播和全國性報紙活動。"},{"en":"Above-the-line items in the income statement reflect core operational performance.","zh-TW":"損益表中的線上項目反映了核心運營績效。"}]', 'phrasal verb'),
('accelerated depreciation', '', '', '[{"en":"Accelerated depreciation reduces taxable income in the early years of an asset.","zh-TW":"加速折舊在資產的前幾年降低了應稅收入。"},{"en":"The tax authorities allow accelerated depreciation for certain qualifying assets.","zh-TW":"稅務機關允許對某些符合條件的資產使用加速折舊。"}]', 'phrasal verb'),
('active management', '', '', '[{"en":"Active management aims to beat benchmark returns through stock selection.","zh-TW":"主動管理旨在通過選股超越基準回報。"},{"en":"Higher fees for active management must be justified by superior returns.","zh-TW":"主動管理的較高費用必須通過卓越回報來證明合理性。"}]', 'phrasal verb'),
('anti-dumping duty', '', '', '[{"en":"The government imposed anti-dumping duties on cheap imported steel.","zh-TW":"政府對進口廉價鋼鐵徵收了反傾銷稅。"},{"en":"An anti-dumping duty investigation requires proof of material injury.","zh-TW":"反傾銷稅調查需要提供實質損害的證明。"}]', 'phrasal verb'),
('asset-backed security', '', '', '[{"en":"The bank securitized its auto loan portfolio into asset-backed securities.","zh-TW":"銀行將其汽車貸款組合證券化為資產擔保證券。"},{"en":"Asset-backed securities allow banks to free up capital for new lending.","zh-TW":"資產擔保證券使銀行能夠釋放資本用於新貸款。"}]', 'phrasal verb'),
('audit committee', '', '', '[{"en":"The audit committee reviewed the external auditor''s findings.","zh-TW":"審計委員會審查了外部審計師的調查結果。"},{"en":"An independent audit committee is required for listed companies.","zh-TW":"上市公司需要設立獨立的審計委員會。"}]', 'phrasal verb'),
('backward integration', '', '', '[{"en":"Backward integration gave the company direct control over raw material supply.","zh-TW":"向後整合使公司直接控制了原材料供應。"},{"en":"Buying out a key supplier is a common backward integration approach.","zh-TW":"收購主要供應商是常見的向後整合方式。"}]', 'phrasal verb'),
('balance of payments', '', '', '[{"en":"A persistent balance of payments deficit may weaken the national currency.","zh-TW":"持續的國際收支赤字可能削弱本國貨幣。"},{"en":"The government implemented trade policies to improve the balance of payments.","zh-TW":"政府實施了貿易政策以改善國際收支。"}]', 'phrasal verb'),
('benchmark index', '', '', '[{"en":"The fund consistently outperformed the benchmark index over five years.","zh-TW":"該基金在五年內持續超越了基準指數。"},{"en":"Portfolio managers are measured against an appropriate benchmark index.","zh-TW":"投資組合管理人按適當的基準指數衡量績效。"}]', 'phrasal verb'),
('bonus scheme', '', '', '[{"en":"The annual bonus scheme rewards employees who exceed their targets.","zh-TW":"年度獎金方案獎勵超過目標的員工。"},{"en":"A transparent bonus scheme improves staff motivation and fairness.","zh-TW":"透明的獎金方案改善了員工積極性和公平性。"}]', 'phrasal verb'),
('brokerage fee', '', '', '[{"en":"The real estate brokerage fee was 3% of the final sale price.","zh-TW":"房地產經紀費為最終成交價格的3%。"},{"en":"Online platforms have reduced brokerage fees for small retail investors.","zh-TW":"在線平台降低了小型零售投資者的經紀費。"}]', 'phrasal verb'),
('bulk cargo', '', '', '[{"en":"The port handled 50 million tonnes of bulk cargo last year.","zh-TW":"港口去年處理了5000萬噸散裝貨物。"},{"en":"Bulk cargo ships are designed to carry large volumes efficiently.","zh-TW":"散裝貨船設計用於高效運載大量貨物。"}]', 'phrasal verb'),
('business process reengineering', '', '', '[{"en":"Business process reengineering reduced order processing time from 10 days to 2.","zh-TW":"業務流程再造將訂單處理時間從10天縮短到了2天。"},{"en":"Successful business process reengineering requires strong leadership commitment.","zh-TW":"成功的業務流程再造需要強有力的領導層承諾。"}]', 'phrasal verb');